<script setup lang="ts">import {computed} from 'vue';import {useRoute} from 'vue-router';import {ArrowRight,BookOpen,FileText,Share2,Settings2,Wrench,CheckCircle2,MapPinned,UsersRound,History} from 'lucide-vue-next';import PageHeader from '../components/PageHeader.vue';import StatusBadge from '../components/StatusBadge.vue';import {initialServices,type ServiceRecord} from '../data/mock';import {useVintro} from '../composables/useVintro';const route=useRoute();const {state}=useVintro();const v=computed(()=>state.vehicles.find(vehicle=>vehicle.id===route.params.id)??state.vehicles[0]);const golfRecent:ServiceRecord={id:'g1',vehicleId:'golf-gti',date:'8 July 2026',dateISO:'2026-07-08',mileage:124600,type:'DSG oil service',category:'Service',workshop:'Servis Škofja Loka',parts:['DSG fluid','Transmission filter'],cost:480,currency:'EUR',verified:true};const isGolf=computed(()=>v.value.id==='golf-gti');const recent=computed(()=>isGolf.value?golfRecent:initialServices[0]);const shortcuts=computed(()=>[{label:'Vehicle timeline',to:`/vehicle/${v.value.id}/timeline`,icon:History},{label:'Service history',to:`/vehicle/${v.value.id}/history`,icon:BookOpen},{label:'Documents',to:`/vehicle/${v.value.id}/documents`,icon:FileText},{label:'Share history',to:`/vehicle/${v.value.id}/share`,icon:Share2},{label:'Specifications',to:`/vehicle/${v.value.id}/specifications`,icon:Settings2},{label:'Manage vehicle',to:`/vehicle/${v.value.id}/settings`,icon:Settings2},{label:'Find workshop',to:'/workshops',icon:MapPinned},{label:'Ownership',to:`/vehicle/${v.value.id}/ownership`,icon:UsersRound}]);const serviceCount=computed(()=>isGolf.value?5:8);const verifiedCount=computed(()=>isGolf.value?3:6);const nextService=computed(()=>isGolf.value?'Vehicle inspection':'Engine oil & filter');const nextDistance=computed(()=>isGolf.value?'3,200 km':'2,580 km');const nextDate=computed(()=>isGolf.value?'January 2027':'November 2026')

</script>
<template><PageHeader title="Vehicle" back="/"/><div class="container-app py-6 md:py-9"><section class="relative overflow-hidden rounded-3xl bg-[#e7e3dc] min-h-[330px] md:min-h-[400px]"><div class="relative z-10 p-6 md:p-10"><p class="eyebrow">{{v.trim}}</p><h1 class="mt-2 text-3xl font-semibold tracking-[-.04em] md:text-5xl">{{v.make}} {{v.model}}</h1><div class="mt-4 flex flex-wrap gap-x-5 gap-y-2 text-sm text-muted"><span>{{v.year}}</span><span>{{v.fuelType}}</span><span>{{v.transmission}}</span><span>{{v.power}}</span></div></div><img :src="v.image" :alt="`${v.make} ${v.model}`" class="absolute inset-x-0 bottom-0 h-[72%] w-full object-cover object-center mix-blend-multiply md:h-[85%]"/></section><div class="mt-6 grid gap-6 lg:grid-cols-[1fr_340px]"><div class="space-y-6"><section><div class="mb-3 flex items-center justify-between"><h2 class="section-title">Vehicle record</h2><StatusBadge :status="v.health"/></div><div class="card grid grid-cols-3 divide-x p-5 text-center"><div><p class="text-xs text-muted">Mileage</p><p class="nums mt-1 font-semibold">{{v.mileage.toLocaleString('en-CH')}} km</p></div><div><p class="text-xs text-muted">Services</p><p class="nums mt-1 font-semibold">{{serviceCount}} records</p></div><div><p class="text-xs text-muted">Verified</p><p class="nums mt-1 font-semibold">{{verifiedCount}} records</p></div></div></section><section><h2 class="section-title mb-3">Shortcuts</h2><div class="grid grid-cols-2 gap-3"><RouterLink v-for="s in shortcuts" :key="s.label" :to="s.to" class="card group p-4 hover:shadow-soft"><component :is="s.icon" :size="21" class="text-accent"/><div class="mt-5 flex items-center justify-between text-sm font-semibold">{{s.label}}<ArrowRight :size="16" class="text-muted transition group-hover:translate-x-1"/></div></RouterLink></div></section><section><div class="mb-3 flex items-center justify-between"><h2 class="section-title">Recent service</h2><RouterLink :to="`/vehicle/${v.id}/history`" class="text-sm font-medium text-accent">View all</RouterLink></div><div class="card p-5"><div class="flex items-start justify-between"><div><p class="nums text-xs text-muted">{{recent.date}} · {{recent.mileage.toLocaleString('en-CH')}} km</p><h3 class="mt-1 text-lg font-semibold">{{recent.type}}</h3></div><CheckCircle2 class="text-success" :size="20"/></div><div class="mt-5 flex justify-between border-t pt-4 text-sm"><span><small class="block text-muted">Workshop</small>{{recent.workshop}}</span><span class="text-right"><small class="block text-muted">Cost</small>{{recent.currency}} {{recent.cost}}</span></div></div></section></div><aside><div class="card sticky top-24 overflow-hidden"><div class="bg-ink p-6 text-white"><div class="flex items-center gap-2 text-sm text-stone-300"><Wrench :size="17"/>Next maintenance</div><h2 class="mt-6 text-2xl font-semibold">{{nextService}}</h2><p class="nums mt-2 text-stone-300">Due in <strong class="text-white">{{nextDistance}}</strong></p></div><div class="p-6"><div class="flex justify-between text-sm"><span class="text-muted">Estimated</span><strong>{{nextDate}}</strong></div><div class="mt-4 h-1.5 overflow-hidden rounded-full bg-stone-200"><div class="h-full w-[83%] rounded-full bg-amber"/></div><RouterLink :to="`/vehicle/${v.id}/maintenance`" class="btn-primary mt-6 w-full">View maintenance<ArrowRight :size="17"/></RouterLink></div></div></aside></div></div></template>
